package com.asmj.marketplace.controller;

import com.asmj.marketplace.approval.*;
import com.asmj.marketplace.model.Role;
import com.asmj.marketplace.model.UserAccount;
import com.asmj.marketplace.repository.UserAccountRepository;
import com.asmj.marketplace.service.CloudinaryImageService;
import java.security.Principal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class ApprovalCenterController {
 private final ApprovalCaseRepository cases; private final UserAccountRepository users; private final CloudinaryImageService uploads; private final ApprovalModuleBridge bridge; private final com.asmj.marketplace.masterdata.MasterDataOptionRepository masterData; private final com.asmj.marketplace.notification.NotificationService notifications;
 public ApprovalCenterController(ApprovalCaseRepository cases,UserAccountRepository users,CloudinaryImageService uploads,ApprovalModuleBridge bridge,com.asmj.marketplace.masterdata.MasterDataOptionRepository masterData,com.asmj.marketplace.notification.NotificationService notifications){this.cases=cases;this.users=users;this.uploads=uploads;this.bridge=bridge;this.masterData=masterData;this.notifications=notifications;}
 private UserAccount current(Principal p){return users.findByEmailIgnoreCase(p.getName()).orElseThrow();}
 private boolean admin(UserAccount u){return u.getRole()==Role.ROLE_ADMIN;}
 @GetMapping("/admin/approval-center") public String adminQueue(Model m){
  List<ApprovalCase> incoming=cases.findTop300ByOrderByUpdatedAtDesc().stream()
   .filter(c -> users.findById(c.getOwnerUserId()).map(u -> u.getRole()!=Role.ROLE_ADMIN).orElse(false)).toList();
  m.addAttribute("cases",incoming);m.addAttribute("incomingCount",incoming.stream().filter(c -> "SUBMITTED".equals(c.getStatus())).count());return "admin/approval-center";
 }
 @GetMapping("/my-approval-requests/new") public String newSubmission(Model m,Principal p){UserAccount u=current(p);if(admin(u))return "auth/access-denied";m.addAttribute("moduleOptions",masterData.findByGroupKeyAndActiveTrueOrderBySortOrderAscLabelAsc("APPROVAL_MODULE"));return "approval/submit-request";}
 @PostMapping("/my-approval-requests/new") public String submitForApproval(@RequestParam String module,@RequestParam String subjectType,@RequestParam String subjectId,@RequestParam(required=false) String message,@RequestParam(required=false) List<MultipartFile> files,Principal p,RedirectAttributes ra){
  UserAccount owner=current(p);if(admin(owner))return "auth/access-denied";
  try {
   UserAccount verified=bridge.validateAndResolveOwner(module,subjectId,owner.getEmail());
   if(!owner.getId().equals(verified.getId()))throw new IllegalArgumentException("You can submit only records belonging to your account.");
   String title=bridge.title(module,subjectId);
   boolean duplicate=cases.findByOwnerUserIdOrderByUpdatedAtDesc(owner.getId()).stream().anyMatch(c->module.equalsIgnoreCase(c.getModule())&&subjectId.equals(c.getSubjectId())&&!List.of("APPROVED","REJECTED").contains(c.getStatus()));
   if(duplicate)throw new IllegalArgumentException("An active approval request already exists for this item. Open it to check its status.");
   if((message==null||message.isBlank())&&(files==null||files.stream().allMatch(f->f==null||f.isEmpty())))throw new IllegalArgumentException("Add a message or at least one supporting document.");
   ApprovalCase c=new ApprovalCase();c.setOwnerUserId(owner.getId());c.setOwnerEmail(owner.getEmail());c.setModule(module.trim().toUpperCase());c.setSubjectType(subjectType.trim());c.setSubjectId(subjectId.trim());c.setSubjectTitle(title);c.setStatus("SUBMITTED");c.setSubmittedAt(Instant.now());c.setUpdatedAt(Instant.now());
   ApprovalEntry entry=new ApprovalEntry(owner.getEmail(),owner.getRole().name(),"SUBMITTED_FOR_APPROVAL",message==null?"":message.trim());addFiles(files,entry,c,owner.getEmail());c.getHistory().add(entry);cases.save(c);notifications.notifyAdmins("New approval request",owner.getFullName()+" submitted "+title,"APPROVAL",c.getId());
   ra.addFlashAttribute("successMessage","Your approval request has been submitted to Admin.");return "redirect:/my-approval-requests/"+c.getId();
  }catch(IllegalArgumentException|IllegalStateException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());return "redirect:/my-approval-requests/new";}
 }
 @GetMapping("/admin/approval-center/{id}") public String adminDetail(@PathVariable String id,Model m,Principal p){if(!admin(current(p)))return "auth/access-denied";ApprovalCase c=cases.findById(id).orElseThrow();if(users.findById(c.getOwnerUserId()).map(u->u.getRole()==Role.ROLE_ADMIN).orElse(true))return "auth/access-denied";m.addAttribute("approvalCase",c);m.addAttribute("requestReasons",masterData.findByGroupKeyAndActiveTrueOrderBySortOrderAscLabelAsc("APPROVAL_REQUEST_REASON"));m.addAttribute("documentTypes",masterData.findByGroupKeyAndActiveTrueOrderBySortOrderAscLabelAsc("APPROVAL_DOCUMENT_TYPE"));return "admin/approval-case-detail";}
 @PostMapping("/admin/approval-center/{id}/request") public String request(@PathVariable String id,@RequestParam String message,@RequestParam(required=false) String requestReason,@RequestParam(required=false) List<String> requestedDocumentTypes,@RequestParam(required=false) List<MultipartFile> files,Principal p,RedirectAttributes ra){UserAccount actor=current(p);if(!admin(actor))return "auth/access-denied";ApprovalCase c=cases.findById(id).orElseThrow();if(users.findById(c.getOwnerUserId()).map(u->u.getRole()==Role.ROLE_ADMIN).orElse(true))return "auth/access-denied";if(message==null||message.isBlank()){ra.addFlashAttribute("errorMessage","Enter the details required from the submitter.");return "redirect:/admin/approval-center/"+id;}ApprovalEntry e=new ApprovalEntry(actor.getEmail(),"ADMIN","INFORMATION_REQUESTED",message.trim());e.setRequestReason(requestReason);e.setRequestedDocumentTypes(requestedDocumentTypes==null?new ArrayList<>():requestedDocumentTypes);addFiles(files,e,c,actor.getEmail());c.getHistory().add(e);c.setLatestAdminMessage(message.trim());c.setStatus("ACTION_REQUIRED");c.setUpdatedAt(Instant.now());c.setDecidedAt(null);c.setDecidedBy(null);cases.save(c);notifications.notifyUser(c.getOwnerUserId(),"Additional information required",message.trim(),"APPROVAL",c.getId());ra.addFlashAttribute("successMessage","Additional information requested.");return "redirect:/admin/approval-center/"+id;}
 @PostMapping("/admin/approval-center/{id}/decision") public String decision(@PathVariable String id,@RequestParam String decision,@RequestParam(required=false) String message,Principal p,RedirectAttributes ra){UserAccount actor=current(p);if(!admin(actor))return "auth/access-denied";ApprovalCase c=cases.findById(id).orElseThrow();if(users.findById(c.getOwnerUserId()).map(u->u.getRole()==Role.ROLE_ADMIN).orElse(true))return "auth/access-denied";String d=decision.toUpperCase();if(!List.of("APPROVED","REJECTED").contains(d)){ra.addFlashAttribute("errorMessage","Invalid decision.");return "redirect:/admin/approval-center/"+id;}if(!"SUBMITTED".equals(c.getStatus())){ra.addFlashAttribute("errorMessage","Wait for the submitter to respond before recording a final decision.");return "redirect:/admin/approval-center/"+id;}try{bridge.applyDecision(c,d,actor.getEmail(),message);}catch(IllegalArgumentException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());return "redirect:/admin/approval-center/"+id;}c.setStatus(d);c.setDecidedAt(Instant.now());c.setDecidedBy(actor.getEmail());c.setUpdatedAt(Instant.now());c.getHistory().add(new ApprovalEntry(actor.getEmail(),"ADMIN",d,message==null?"":message.trim()));cases.save(c);notifications.notifyUser(c.getOwnerUserId(),"Approval request "+d.toLowerCase(),"Your "+c.getModule()+" request for "+c.getSubjectTitle()+" was "+d.toLowerCase()+"."+(message==null||message.isBlank()?"":" "+message.trim()),"APPROVAL",c.getId());ra.addFlashAttribute("successMessage","Approval case marked "+d.toLowerCase()+".");return "redirect:/admin/approval-center/"+id;}
 @GetMapping("/my-approval-requests") public String myRequests(Principal p,Model m){UserAccount u=current(p);if(admin(u))return "auth/access-denied";m.addAttribute("cases",cases.findByOwnerUserIdOrderByUpdatedAtDesc(u.getId()));return "approval/my-requests";}
 @GetMapping("/my-approval-requests/{id}") public String myDetail(@PathVariable String id,Principal p,Model m){UserAccount u=current(p);if(admin(u))return "auth/access-denied";ApprovalCase c=cases.findById(id).filter(x->u.getId().equals(x.getOwnerUserId())).orElseThrow();m.addAttribute("approvalCase",c);return "approval/request-detail";}
 @PostMapping("/my-approval-requests/{id}/respond") public String respond(@PathVariable String id,@RequestParam(required=false) String message,@RequestParam(required=false) List<MultipartFile> files,Principal p,RedirectAttributes ra){UserAccount u=current(p);if(admin(u))return "auth/access-denied";ApprovalCase c=cases.findById(id).filter(x->u.getId().equals(x.getOwnerUserId())).orElseThrow();if(!"ACTION_REQUIRED".equals(c.getStatus())){ra.addFlashAttribute("errorMessage","This request is not currently awaiting your response.");return "redirect:/my-approval-requests/"+id;}if((message==null||message.isBlank())&&(files==null||files.stream().allMatch(f->f==null||f.isEmpty()))){ra.addFlashAttribute("errorMessage","Enter a response or attach at least one file.");return "redirect:/my-approval-requests/"+id;}ApprovalEntry e=new ApprovalEntry(u.getEmail(),u.getRole().name(),"SUBMITTED_FOR_REVIEW",message==null?"":message.trim());try{addFiles(files,e,c,u.getEmail());}catch(IllegalArgumentException|IllegalStateException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());return "redirect:/my-approval-requests/"+id;}c.getHistory().add(e);c.setStatus("SUBMITTED");c.setSubmittedAt(Instant.now());c.setUpdatedAt(Instant.now());cases.save(c);notifications.notifyAdmins("Approval response received",u.getFullName()+" responded to "+c.getSubjectTitle(),"APPROVAL",c.getId());ra.addFlashAttribute("successMessage","Your response has been submitted for admin review.");return "redirect:/my-approval-requests/"+id;}
 private void addFiles(List<MultipartFile> files,ApprovalEntry entry,ApprovalCase c,String by){if(files==null)return;for(MultipartFile f:files){if(f==null||f.isEmpty())continue;Map<String,Object> result=uploads.uploadDocument(f,"asmj-marketplace/approval-documents");ApprovalAttachment a=new ApprovalAttachment(f.getOriginalFilename(),String.valueOf(result.get("secure_url")),f.getContentType(),by);entry.getAttachments().add(a);c.getAttachments().add(a);}}
}
